-- Contract test for 20260925150340_remove_test_tenants_v1. Restores the production backup (supabase/backups/20260925_test_tenants.sql,
-- copied below) into the local database, runs the migration (copied below) and checks that only the test companies went away.
-- Self-contained because contracts are piped into psql. One transaction, rolled back.
-- psql -v ON_ERROR_STOP=1 -f tests/security/remove-test-tenants-contract.sql

begin;

create temp table results (check_name text, ok boolean);
create temp table before_counts as
select (select count(*) from public.organizations) as orgs, (select count(*) from public.organization_roles) as roles,
       (select count(*) from public.organization_memberships) as members;

-- The three production logins referenced by the backup (only the Tenant A login is removed).
insert into auth.users (id, instance_id, aud, role, email)
select v.id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', v.email
from (values ('d60aa9a9-6f73-4261-b843-7a15227d3300'::uuid, 'tenant-a-login@corban-teste.local'),
             ('9917cdc3-bca0-4249-91a4-20fec75ef26a'::uuid, 'smart-admin@corban-teste.local'),
             ('e9af738c-cfea-4994-b28c-23d774ad19d6'::uuid, 'platform-admin@corban-teste.local')) v(id, email)
where not exists (select 1 from auth.users u where u.id = v.id);

-- Restore the backup the documented way: organizations triggers off, so no second set of defaults is created.
alter table public.organizations disable trigger organizations_10_default_roles;
alter table public.organizations disable trigger organizations_20_default_modules;
alter table public.organizations disable trigger organizations_30_default_stages;
