insert into results select 'backup restores the 69 rows',
  (select count(*) from public.organizations where id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 2
  and (select count(*) from public.organization_branches where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 2
  and (select count(*) from public.organization_roles where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 14
  and (select count(*) from public.organization_modules where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 30
  and (select count(*) from public.operational_stages where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 16
  and (select count(*) from public.organization_memberships where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 2
  and (select count(*) from public.platform_admin_audit_events where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 3;

create temp table mig (sql text);
insert into mig values ($mig$-- Remove the two test companies created for the RLS checks of 18/09/2026, and the login used only for them (owner decision 25/09/2026).
-- Backup of every removed row: supabase/backups/20260925_test_tenants.sql.
--
-- Fail-closed: the removal stops, and nothing is deleted, if either company holds a row in any table other than the default
-- configuration created with it (branches, roles, modules, pipeline stages), its memberships and the platform audit events
-- about it; or if the test login belongs to any other company. The real company (Smart Promotora) is never touched.

do $$
declare
  v_orgs uuid[] := array['9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9']::uuid[];
  v_login uuid := 'd60aa9a9-6f73-4261-b843-7a15227d3300';
  v_allowed text[] := array['public.organization_branches', 'public.organization_roles', 'public.organization_modules',
    'public.operational_stages', 'public.organization_memberships', 'public.platform_admin_audit_events'];
  r record;
  n bigint;
begin
  for r in
    select c.table_schema || '.' || c.table_name as tbl, c.table_schema as s, c.table_name as t
    from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name and t.table_type = 'BASE TABLE'
    where c.column_name = 'organization_id' and c.table_schema not in ('pg_catalog', 'information_schema')
  loop
    if r.tbl = any (v_allowed) then continue; end if;
    execute format('select count(*) from %I.%I where organization_id = any ($1)', r.s, r.t) into n using v_orgs;
    if n > 0 then raise exception 'test_tenant_has_data: % (% rows)', r.tbl, n; end if;
  end loop;

  if exists (select 1 from public.organization_memberships where user_id = v_login and not (organization_id = any (v_orgs))) then
    raise exception 'test_login_belongs_to_another_company';
  end if;

  delete from public.platform_admin_audit_events where organization_id = any (v_orgs);
  delete from public.organization_memberships where organization_id = any (v_orgs);
  delete from public.operational_stages where organization_id = any (v_orgs);
  delete from public.organization_modules where organization_id = any (v_orgs);
  delete from public.organization_branches where organization_id = any (v_orgs);

  -- Roles are never deleted through the app (organization_roles_00_guard). The guard is lifted for these two companies only,
  -- inside this transaction, and restored right after.
  alter table public.organization_roles disable trigger organization_roles_00_guard;
  delete from public.organization_roles where organization_id = any (v_orgs);
  alter table public.organization_roles enable trigger organization_roles_00_guard;

  delete from public.organizations where id = any (v_orgs);
  delete from auth.users where id = v_login;
end
$$;
$mig$);

-- Fail-closed: a client in a test company stops the removal and nothing is deleted.
insert into public.clients (organization_id, cpf, full_name, original_source)
values ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '52998224725', 'Cliente no Tenant A', 'manual');
do $$ begin
  begin
    execute (select sql from mig);
    insert into results values ('a test company with data is not removed', false);
  exception when others then
    insert into results values ('a test company with data is not removed', sqlerrm like 'test_tenant_has_data: public.clients%'
      and (select count(*) from public.organizations where id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9')) = 2);
  end;
end $$;
delete from public.clients where organization_id = '9116a949-18f1-4cb0-aeb8-2c89e7ea882a';

do $$ begin execute (select sql from mig); end $$;

insert into results select 'both test companies are gone', not exists (select 1 from public.organizations where id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'));
insert into results select 'no row of theirs is left',
  not exists (select 1 from public.organization_roles where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'))
  and not exists (select 1 from public.organization_modules where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'))
  and not exists (select 1 from public.operational_stages where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'))
  and not exists (select 1 from public.organization_branches where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'))
  and not exists (select 1 from public.organization_memberships where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'))
  and not exists (select 1 from public.platform_admin_audit_events where organization_id in ('9116a949-18f1-4cb0-aeb8-2c89e7ea882a', '9cd3c149-9622-4442-9e26-45230987c3b9'));
insert into results select 'the Tenant A login is removed', not exists (select 1 from auth.users where id = 'd60aa9a9-6f73-4261-b843-7a15227d3300');
insert into results select 'the other two logins stay', (select count(*) from auth.users where id in ('9917cdc3-bca0-4249-91a4-20fec75ef26a', 'e9af738c-cfea-4994-b28c-23d774ad19d6')) = 2;
insert into results select 'every other company is untouched', (select count(*) from public.organizations) = (select orgs from before_counts)
  and (select count(*) from public.organization_roles) = (select roles from before_counts)
  and (select count(*) from public.organization_memberships) = (select members from before_counts);
insert into results select 'the role guard is back on', exists (select 1 from pg_trigger where tgname = 'organization_roles_00_guard' and tgenabled = 'O');

select check_name, ok from results order by ok, check_name;
do $$ begin
  if (select count(*) from results) <> 8 or exists (select 1 from results where not ok) then raise exception 'remove test tenants contract failed'; end if;
end $$;

rollback;
